import React, { useState } from 'react';
import './css_files/analyzer.css';

const TwitterAnalyzer = () => {
  const [userInput, setUserInput] = useState('');
  const [sentiment, setSentiment] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e) => {
    setUserInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = `${e.target.scrollHeight}px`;
  };

  const analyzeSentiment = async () => {
    if (!userInput.trim()) return;

    setIsLoading(true);
    try {
      const response = await fetch('http://localhost:5000/predictTweet', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ text: userInput })
      });

      const data = await response.json();
      setSentiment(data);
    } catch (error) {
      console.error('Error fetching sentiment:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const getCompoundMarkerPosition = (score) => {
    return ((score + 1) / 2) * 100;
  };

  return (
    <div className="analyzer-container">
      <div className="analyzer-card">
        <h2 className="analyzer-heading">Twitter Sentiment Analysis</h2>
        <p className="analyzer-subheading">Analyze the sentiment of any tweet or text</p>

        <div className="analyzer-content">
          <div className="input-section">
            <h3>Enter Tweet</h3>
            <textarea
              value={userInput}
              onChange={handleInputChange}
              placeholder="Type your tweet here..."
            />
            <button
              className={`analyze-btn ${isLoading ? 'loading' : ''}`}
              onClick={analyzeSentiment}
              disabled={isLoading}
            >
              {isLoading ? (
                <>
                  <span className="loading-spinner"></span>
                  Analyzing...
                  <span className="loading-wave"></span>
                </>
              ) : 'Analyze'}
            </button>
          </div>

          <div className="result-section">
            <h3>Analysis Results</h3>

            {isLoading && (
              <div className="loading-results">
                <div className="spinner"></div>
                <p>Analyzing sentiment...</p>
              </div>
            )}

            {!isLoading && !sentiment && (
              <div className="no-result">
                <svg className="empty-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"></path>
                </svg>
                <p>Analysis results will appear here</p>
              </div>
            )}

            {!isLoading && sentiment && (
              <div>
                <div style={{ textAlign: 'center' }}>
                  <div className={`sentiment-badge ${sentiment.sentiment.toLowerCase()}`}>
                    {sentiment.sentiment}
                  </div>
                  <p style={{ marginTop: '0.5rem', fontSize: '0.9rem' }}>
                    Confidence: {(sentiment.confidence * 100).toFixed(2)}%
                  </p>
                </div>

                <div className="score-details">
                  <h4>Sentiment Scores:</h4>

                  {['positive', 'neutral', 'negative'].map((key) => (
                    <div className="score-item" key={key}>
                      <span>{key.charAt(0).toUpperCase() + key.slice(1)}</span>
                      <div className="score-bar">
                        <div
                          className={`score-fill ${key}`}
                          style={{ width: `${sentiment.vader_score[key] * 100}%` }}
                        ></div>
                      </div>
                      <span className="score-value">{(sentiment.vader_score[key] * 100).toFixed(1)}%</span>
                    </div>
                  ))}

                  <div className="score-item compound-score" style={{ marginTop: '1.5rem' }}>
                    <span>Compound</span>
                    <div className="score-bar compound-bar">
                      <div
                        className="compound-marker"
                        style={{
                          left: `${getCompoundMarkerPosition(sentiment.vader_score.compound)}%`
                        }}
                      ></div>
                    </div>
                    <div className="compound-labels">
                      <span>-1.0</span>
                      <span>0</span>
                      <span>+1.0</span>
                    </div>
                    <span className="score-value">{sentiment.vader_score.compound.toFixed(3)}</span>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="analyzer-footer">
          <p>Powered by machine learning • Twitter-RoBERTa + VADER-inspired scores</p>
        </div>
      </div>
    </div>
  );
};

export default TwitterAnalyzer;
